import {MONSTER_CATALOG} from '../engine2/monster-catalog.js?v=5.38';
import {cutoutAtlas} from '../engine2/sprite-cutout.js';import {supplyCanvas} from '../engine2/supply-art.js';
import {ITEMS,NEW_ITEMS} from '../engine2/repertoire.js?v=5.38';import {prepareBestiary,prepareExtraBestiary} from '../engine2/bestiary-art.js';
const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src='../engine2/art/bestiary.webp';}),art=prepareBestiary(image),drawings=[];
const extraImage=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src='../engine2/art/bestiary2.webp';}),arts={bestiary:art,bestiary2:prepareExtraBestiary(extraImage)};
const frontierImage=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src='../engine2/art/bestiary3.webp';});arts.bestiary3=cutoutAtlas(frontierImage,6,4);
for(const s of MONSTER_CATALOG){const a=document.createElement('article');a.dataset.search=[s.name,s.role,s.habitat,s.move,s.status,s.trait||''].join(' ').toLowerCase();const canvas=document.createElement('canvas');canvas.width=256;canvas.height=192;canvas.setAttribute('aria-label',s.name);a.append(canvas);const h=document.createElement('h3');h.textContent=s.name;a.append(h);for(const text of [s.habitat,s.move,s.tell,s.lore||'',s.trait?'Behavior: '+s.trait+' · watch the charged action before choosing your supply.':'',s.element+' · '+s.role+' · '+(s.adaptation||'native')+' · creature tier '+s.chapter]){const p=document.createElement('p');p.textContent=text;a.append(p);}document.querySelector('#monsters').append(a);drawings.push({canvas,s,visible:true});}
for(const i of ITEMS){const a=document.createElement('article');a.dataset.search=[i.name,i.effect,i.description].join(' ').toLowerCase();a.dataset.item=i.id;const h=document.createElement('h3');h.textContent=i.name;a.append(h);const p=document.createElement('p');p.textContent=i.description;a.append(p);const c=document.createElement('small');c.className='chip';c.textContent=i.price+' credits · shop chapter '+i.chapter;a.append(c);document.querySelector('#items').append(a);}
document.querySelector('#search').oninput=e=>{for(const a of document.querySelectorAll('article'))a.hidden=!a.dataset.search.includes(e.target.value.toLowerCase());};
const observer=new IntersectionObserver(entries=>{for(const e of entries){const d=drawings.find(d=>d.canvas===e.target);if(d)d.visible=e.isIntersecting;} });drawings.forEach(d=>observer.observe(d.canvas));let last=0;
function frame(ms){if(ms-last>100&&!document.hidden){last=ms;for(const {canvas,s,visible} of drawings){if(!visible||canvas.parentElement.hidden)continue;const art=arts[s.atlas||'bestiary'],c=canvas.getContext('2d'),b=art.bounds[s.sprite],h=150+Math.sin(ms*.002+s.sprite),w=h*b.w/b.h;c.clearRect(0,0,256,192);c.fillStyle='#0004';c.beginPath();c.ellipse(128,175,50,7,0,0,7);c.fill();c.save();if(s.hue)c.filter='hue-rotate('+s.hue+'deg)';c.drawImage(art.image,b.x,b.y,b.w,b.h,128-w/2,175-h,w,h);c.restore();}}requestAnimationFrame(frame);}requestAnimationFrame(frame);

const supplies=await new Promise(resolve=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>resolve(null);i.src='../engine2/art/supplies.webp';});NEW_ITEMS.forEach((item,index)=>{if(index>=24||!supplies){const emblem=supplyCanvas(item,112);emblem.classList.add('item-icon');document.querySelector('[data-item="'+item.id+'"]').prepend(emblem);return;}const c=document.createElement('canvas');c.width=160;c.height=160;c.className='item-icon';c.setAttribute('aria-label',item.name);c.getContext('2d').drawImage(supplies,index%6*supplies.width/6,Math.floor(index/6)*supplies.height/4,supplies.width/6,supplies.height/4,0,0,160,160);document.querySelector('[data-item="'+item.id+'"]').prepend(c);});
